function (logs) {
  if (logs.length === 0) return "Nothing was printed. Use console.log with your message in quotes.";
  if (logs.length > 1) return "Print just one message for this stage.";
  if (!logs[0].trim()) return "Your message is empty. Put some words between the quotes.";
  if (logs[0].trim() === "Hello, world!") return "That's the old message. Change the words between the quotes to your own.";
  return true;
}

